    const alignFabricObject = (_2, canvas, alignment) => {
      const obj = canvas.getActiveObject();
      if (!obj) return;
      const canvasWidth = canvas.getWidth();
      const canvasHeight = canvas.getHeight();
      const objWidth = obj.width * obj.scaleX;
      const objHeight = obj.height * obj.scaleY;
      switch (alignment) {
        case "left":
          obj.set({ left: objWidth / 2 });
          break;
        case "center":
          obj.set({ left: canvasWidth / 2 });
          break;
        case "right":
          obj.set({ left: canvasWidth - objWidth / 2 });
          break;
        case "top":
          obj.set({ top: objHeight / 2 });
          break;
        case "middle":
          obj.set({ top: canvasHeight / 2 });
          break;
        case "bottom":
          obj.set({ top: canvasHeight - objHeight / 2 });
          break;
      }
      obj.setCoords();
      canvas.renderAll();
    };
    const updateArrange = (action) => {
      if (!editor || !editor.canvas) return;
      const canvas = editor.canvas;
      const obj = canvas.getActiveObject();
      if (!obj) return;
      const objects2 = canvas.getObjects();
      const currentIndex = objects2.indexOf(obj);
      if (currentIndex === -1) return;
      switch (action) {
        case "bringToFront":
          if (currentIndex < objects2.length - 1) {
            canvas.remove(obj);
            canvas.add(obj);
          }
          break;
        case "sendToBack":
          if (currentIndex > 0) {
            canvas.remove(obj);
            const newObjects = [obj, ...objects2.filter((o2) => o2 !== obj)];
            canvas._objects = newObjects;
            canvas.renderAll();
          }
          break;
        case "bringForward":
          if (currentIndex < objects2.length - 1) {
            const nextIndex = currentIndex + 1;
            [objects2[currentIndex], objects2[nextIndex]] = [objects2[nextIndex], objects2[currentIndex]];
            canvas.renderAll();
          }
          break;
        case "sendBackward":
          if (currentIndex > 0) {
            const prevIndex = currentIndex - 1;
            [objects2[currentIndex], objects2[prevIndex]] = [objects2[prevIndex], objects2[currentIndex]];
            canvas.renderAll();
          }
          break;
      }
      obj.setCoords();
      canvas.renderAll();
    };
